import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.regex.Pattern;
import java.util.logging.Logger;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final Pattern ALPHANUM = Pattern.compile("^[a-zA-Z0-9_]+$");

    // Connection pool managed externally
    private DataSource ds;

    @Override
    public void init(ServletConfig config) throws ServletException {
        super.init(config);
        try {
            javax.naming.Context ctx = new javax.naming.InitialContext();
            ds = (DataSource) ctx.lookup("java:comp/env/jdbc/ReportDB");
        } catch (Exception e) {
            throw new ServletException("Failed to initialize datasource", e);
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {

        String reportType = req.getParameter("type");
        String dateFrom = req.getParameter("from");
        String dateTo = req.getParameter("to");
        String sortCol = req.getParameter("sort");
        String department = req.getParameter("dept");

        // Validate report type strictly
        if (reportType == null || !ALPHANUM.matcher(reportType).matches()) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Date validation - looks secure but only checks format loosely
        if (dateFrom != null && dateFrom.length() > 10) {
            resp.sendError(400, "Invalid date format");
            return;
        }
        if (dateTo != null && dateTo.length() > 10) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Sort column validation - whitelist approach
        String[] allowedSorts = {"created_at", "amount", "department", "status"};
        boolean validSort = false;
        if (sortCol != null) {
            for (String s : allowedSorts) {
                if (s.equals(sortCol)) { validSort = true; break; }
            }
            if (!validSort) sortCol = "created_at";
        } else {
            sortCol = "created_at";
        }

        // Department filter - THIS IS THE VULNERABILITY
        // Developer assumed the frontend dropdown only sends valid dept codes
        // but the parameter is not sanitized before inclusion in query
        StringBuilder query = new StringBuilder();
        query.append("SELECT id, created_at, amount, department, status FROM reports_")
             .append(reportType)  // safe - validated above
             .append(" WHERE created_at >= ? AND created_at <= ?");

        if (department != null && !department.isEmpty()) {
            // Intended to filter by department but concatenates directly
            query.append(" AND department = '").append(department).append("'");
        }

        query.append(" ORDER BY ").append(sortCol);  // safe - whitelisted
        query.append(" LIMIT 500");

        log.info("Executing report query for type=" + reportType);

        try (Connection conn = ds.getConnection();
             PreparedStatement ps = conn.prepareStatement(query.toString())) {

            ps.setString(1, dateFrom != null ? dateFrom : "2020-01-01");
            ps.setString(2, dateTo != null ? dateTo : "2030-12-31");

            ResultSet rs = ps.executeQuery();

            resp.setContentType("application/json");
            java.io.PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("{\"id\":%d,\"date\":\"%s\",\"amount\":%.2f,\"dept\":\"%s\",\"status\":\"%s\"}",
                    rs.getInt(1), rs.getString(2), rs.getDouble(3), rs.getString(4), rs.getString(5));
                first = false;
            }
            out.print("\n]");

        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }
}
